using System;using System.Collections.Generic;using UnityEngine;using UnityEngine.UI;using MultiFPS;using MultiFPS.UI;using Mirror;using ROM.UI.Gameplay;
namespace ROM.EditorTools {
public static class RiftCartographyReview {
 static int cursor;static bool pending;static Vector3 wanted,original;static int health,maxHealth;static RiftFieldUI owner;static GameObject traces;static readonly float[] Fractions={0,.125f,.375f,.5f,.625f,.875f,1};
 static void Require(bool value,string message){if(!value)throw new Exception("Cartography: "+message);}
 static float Cross(Vector2 a,Vector2 b,Vector2 c)=>(b.x-a.x)*(c.y-a.y)-(b.y-a.y)*(c.x-a.x);
 public static List<string> Validate(RiftFieldUI map){var output=new List<string>();var projection=map.Projection;Require(projection!=null,"illustrated calibration loaded");var data=projection.Data;Require(data.From.Length>=200&&data.Routes.Length==9,"bridge and path anchor set complete");float sourceArea=0,targetArea=0;var edges=new Dictionary<string,int>();for(int i=0;i<data.Triangles.Length;i+=3){int a=data.Triangles[i],b=data.Triangles[i+1],c=data.Triangles[i+2];float s=Cross(data.From[a],data.From[b],data.From[c]),t=Cross(data.To[a],data.To[b],data.To[c]);Require(s>0&&t>0,"no folded or degenerate triangles");sourceArea+=s*.5f;targetArea+=t*.5f;int[] tri={a,b,c};for(int j=0;j<3;j++){int lo=Mathf.Min(tri[j],tri[(j+1)%3]),hi=Mathf.Max(tri[j],tri[(j+1)%3]);string key=lo+":"+hi;edges[key]=edges.TryGetValue(key,out var count)?count+1:1;}}
 Require(Mathf.Abs(sourceArea-1)<.00001f&&Mathf.Abs(targetArea-1)<.00001f,"source and target cover complete square domain");int boundary=0;foreach(var edge in edges){Require(edge.Value==1||edge.Value==2,"manifold triangulation");if(edge.Value==1)boundary++;}Require(boundary==4,"four straight boundary edges prevent holes and overlapping outer boundary");output.Add(data.From.Length+" anchors / "+projection.TriangleCount+" positive manifold triangles, complete source and target domain");
 float inverseMax=0;for(int y=0;y<=20;y++)for(int x=0;x<=20;x++){var uv=new Vector2(x/20f,y/20f);Vector2 back=default;Require(projection.TryMap(uv,out var art)&&projection.TryInverse(art,out back),"grid bidirectional coverage");inverseMax=Mathf.Max(inverseMax,Vector2.Distance(uv,back)*data.WorldSize.x);}Require(inverseMax<.04f,"grid inverse precision");Require(!projection.TryMap(new Vector2(-.1f,.5f),out _)&&!projection.TryInverse(new Vector2(1.1f,.5f),out _),"outside domain rejected without extrapolation");output.Add("441 grid round trips, max world error "+inverseMax.ToString("F5")+" m; out-of-domain rejected");
 foreach(var route in data.Routes){float worst=0;for(int i=0;i<=40;i++){float u=i/40f;var p=RoutePoint(route,u);Vector3 world=default;Require(map.TryPosition(p,out var local)&&map.TryWorldPosition(local,out world),"bridge inverse");Require(Vector2.Distance(new Vector2(p.x,p.z),new Vector2(world.x,world.z))<.04f,"bridge round trip precision");Require(projection.TryMap(projection.WorldUV(p),out var uv),"bridge domain");var pixel=new Vector2(uv.x*data.ArtSize,(1-uv.y)*data.ArtSize);worst=Mathf.Max(worst,Vector2.Distance(pixel,Vector2.Lerp(route.ArtStart,route.ArtEnd,u)));foreach(float yaw in new[]{0f,45f,90f,180f,270f})Require(map.Heading(p,yaw).sqrMagnitude>.00000001f,"projected heading is nonzero");}Require(worst<1.25f,"bridge centerline leaves illustrated corridor: "+route.Name+" error "+worst);output.Add("41 bridge corridor hold-outs / inverse / 5 headings: "+route.Name+" max "+worst.ToString("F3")+" px");}
  int roads=0;foreach(var renderer in UnityEngine.Object.FindObjectsByType<MeshRenderer>(FindObjectsSortMode.None)){if(!(renderer.name.EndsWith(" - sendero")||renderer.name=="Avenida del distrito"||renderer.name=="Camino de tierra y losas"))continue;var point=renderer.bounds.center;Vector3 back=default;Require(map.TryPosition(point,out var local)&&map.TryWorldPosition(local,out back),"surveyed island road domain and inverse");Require(Vector2.Distance(new Vector2(point.x,point.z),new Vector2(back.x,back.z))<.04f,"surveyed island road precision");roads++;}Require(roads>=90,"actual rendered road sample catalog");output.Add(roads+" actual rendered island/village road centers have bidirectional mapping within 4 cm");var frame=map.MapPanel.Find("Cartography viewport border") as RectTransform;Require(frame&&frame.parent==map.MapPanel&&Vector2.Distance(frame.rect.size,map.Viewport.rect.size)<.01f&&frame.localScale==Vector3.one,"viewport frame remains independent of texture zoom");output.Add("Inner viewport frame preserves clip extent, input and scale independently of map texture");Require(!map.MapButton.gameObject.activeSelf,"legacy gold map button hidden while M open");output.Add("Legacy MAPA button hidden while full map is open");return output;}
 static Vector3 RoutePoint(RiftCartographicProjection.Route route,float u)=>Vector3.Lerp(new Vector3(route.FromWorld[0],route.FromWorld[1],route.FromWorld[2]),new Vector3(route.ToWorld[0],route.ToWorld[1],route.ToWorld[2]),u);
 public static void Start(RiftFieldUI map){owner=map;cursor=0;pending=false;var actor=ClientFrontend.ClientPlayerInstance.MyCharacter;original=actor.transform.position;health=actor.Health.CurrentHealth;maxHealth=actor.Health.MaxHealth;actor.Health.ServerSetVitals(10000,10000);map.SetMap(true);map.GetComponent<RiftModernMapFrame>().FitOverview();traces=new GameObject("EDITOR ONLY cartographic corridor traces",typeof(RectTransform));var root=(RectTransform)traces.transform;root.SetParent(map.Content,false);root.anchorMin=root.anchorMax=root.pivot=new Vector2(.5f,.5f);root.sizeDelta=Vector2.zero;foreach(var route in map.Projection.Data.Routes)for(int j=0;j<=40;j++){var go=new GameObject("Measured bridge sample",typeof(RectTransform),typeof(Image));var rect=(RectTransform)go.transform;rect.SetParent(root,false);rect.anchorMin=rect.anchorMax=rect.pivot=new Vector2(.5f,.5f);rect.anchoredPosition=map.Position(RoutePoint(route,j/40f));rect.sizeDelta=Vector2.one*2;var image=go.GetComponent<Image>();image.color=new Color(.4f,1,1,.85f);image.raycastTarget=false;}}
 public static bool LiveStep(){var actor=ClientFrontend.ClientPlayerInstance.MyCharacter;if(pending){Require(Vector2.Distance(new Vector2(actor.transform.position.x,actor.transform.position.z),new Vector2(wanted.x,wanted.z))<.4f,"server actor remained on sampled bridge point");Require(Vector2.Distance(owner.PlayerMarker.anchoredPosition,owner.Position(actor.transform.position))<.05f,"live player marker follows sampled server actor");float yaw=actor.Input.LookY;var h=owner.Heading(actor.transform.position,yaw);float angle=-Mathf.Atan2(h.x,h.y)*Mathf.Rad2Deg;Require(Mathf.Abs(Mathf.DeltaAngle(owner.PlayerMarker.localEulerAngles.z,angle))<.2f,"live arrow uses projected heading");pending=false;cursor++;}
 if(cursor>=owner.Projection.Data.Routes.Length*Fractions.Length){UnityEngine.Object.Destroy(traces);actor.ServerTeleport(original,0);actor.Health.ServerSetVitals(health,maxHealth);return false;}
 var route=owner.Projection.Data.Routes[cursor/Fractions.Length];wanted=RoutePoint(route,Fractions[cursor%Fractions.Length]);actor.ServerTeleport(wanted+Vector3.up*1.4f,45);pending=true;return true;}
 }
}
